export type Patient = {
  id: string;
  display_name: string;
  date_of_birth: string | null;
  created_at: string;
};

export type DocumentSummary = {
  id: string;
  patient_id: string;
  filename: string;
  original_filename: string;
  document_type: string;
  page_count: number;
  uploaded_at: string;
  source_label: string | null;
  scenario_tag: string | null;
};

export type PageText = {
  page_number: number;
  text: string;
};

export type DocumentDetail = DocumentSummary & {
  pages: PageText[];
};

import type { DocumentDetail, DocumentSummary, Patient } from "./types";

const API_BASE =
  process.env.NEXT_PUBLIC_API_BASE_URL?.replace(/\/$/, "") ??
  "http://localhost:8000";

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(`${API_BASE}${path}`, init);
  if (!response.ok) {
    const detail = await response.text();
    throw new Error(detail || `Request failed (${response.status})`);
  }
  return response.json() as Promise<T>;
}

export function getApiBase() {
  return API_BASE;
}

export function listPatients() {
  return request<Patient[]>("/api/patients");
}

export function getPatient(patientId: string) {
  return request<Patient>(`/api/patients/${patientId}`);
}

export function listDocuments(patientId: string) {
  return request<DocumentSummary[]>(`/api/patients/${patientId}/documents`);
}

export function getDocument(patientId: string, documentId: string) {
  return request<DocumentDetail>(
    `/api/patients/${patientId}/documents/${documentId}`,
  );
}

export function documentFileUrl(patientId: string, documentId: string) {
  return `${API_BASE}/api/patients/${patientId}/documents/${documentId}/file`;
}

export async function uploadDocument(
  patientId: string,
  file: File,
  documentType = "clinical_note",
) {
  const body = new FormData();
  body.append("file", file);
  body.append("document_type", documentType);
  body.append("source_label", file.name);
  return request<DocumentSummary>(`/api/patients/${patientId}/documents`, {
    method: "POST",
    body,
  });
}

export async function reseedDemo() {
  return request<{
    patient_id: string;
    documents_created: number;
    document_ids: string[];
  }>("/api/demo/seed", { method: "POST" });
}

@import "tailwindcss";

:root {
  --ink: #102a2e;
  --ink-soft: #2a4a4f;
  --mist: #e7eef0;
  --paper: #f3f7f8;
  --accent: #1b7a6d;
  --accent-deep: #0f5a51;
  --line: #c7d4d7;
  --muted: #5d7277;
  --warning: #8a6230;
  --background: var(--paper);
  --foreground: var(--ink);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-ink: var(--ink);
  --color-ink-soft: var(--ink-soft);
  --color-mist: var(--mist);
  --color-paper: var(--paper);
  --color-accent: var(--accent);
  --color-accent-deep: var(--accent-deep);
  --color-line: var(--line);
  --color-muted: var(--muted);
  --color-warning: var(--warning);
  --font-sans: var(--font-figtree);
  --font-display: var(--font-fraunces);
}

body {
  background:
    radial-gradient(ellipse 80% 50% at 10% -10%, #d7ebe7 0%, transparent 55%),
    radial-gradient(ellipse 60% 40% at 100% 0%, #dce6ea 0%, transparent 50%),
    linear-gradient(165deg, #eef4f5 0%, var(--paper) 45%, #e8f0f1 100%);
  color: var(--foreground);
  font-family: var(--font-figtree), sans-serif;
  min-height: 100vh;
}

body::before {
  content: "";
  pointer-events: none;
  position: fixed;
  inset: 0;
  background-image:
    linear-gradient(rgba(16, 42, 46, 0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(16, 42, 46, 0.03) 1px, transparent 1px);
  background-size: 28px 28px;
  mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 0.55), transparent 85%);
  z-index: 0;
}

@keyframes rise-in {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes pulse-soft {
  0%,
  100% {
    opacity: 0.55;
  }
  50% {
    opacity: 1;
  }
}

.animate-rise {
  animation: rise-in 0.55s ease-out both;
}

.animate-fade {
  animation: fade-in 0.4s ease-out both;
}

.stagger-1 {
  animation-delay: 0.05s;
}
.stagger-2 {
  animation-delay: 0.12s;
}
.stagger-3 {
  animation-delay: 0.2s;
}
.stagger-4 {
  animation-delay: 0.28s;
}

.uploading-pulse {
  animation: pulse-soft 1.2s ease-in-out infinite;
}

type PlaceholderPanelProps = {
