from __future__ import annotations

from dataclasses import dataclass
from itertools import combinations

from sqlalchemy.orm import Session, joinedload

from app.models.db import Document, EvidenceCandidate
from app.services.evidence_verification import (
    CANDIDATE_ACCEPTED,
    STATUS_NEEDS_REVIEW,
    STATUS_NOT_ESTABLISHED,
    STATUS_SUPPORTED,
    PolicyEvaluation,
    evaluate_patient_policy,
)
from app.services.policy import FICTIONAL_POLICY_ID, REQUIREMENTS_BY_ID


@dataclass(frozen=True)
class PacketDocument:
    document_id: str
    source_label: str
    original_filename: str
    document_type: str
    page_count: int
    covers_requirement_ids: tuple[str, ...]
    covers_requirement_titles: tuple[str, ...]


@dataclass(frozen=True)
class MissingEvidenceItem:
    requirement_id: str
    title: str
    status: str
    explanation: str
    suggested_document_types: tuple[str, ...]


@dataclass(frozen=True)
class EvidencePacket:
    patient_id: str
    policy_id: str
    policy_name: str
    disclaimer: str
    covered_requirement_ids: tuple[str, ...]
    uncovered_requirement_ids: tuple[str, ...]
    selected_documents: tuple[PacketDocument, ...]
    omitted_document_ids: tuple[str, ...]
    total_pages: int
    missing_evidence: tuple[MissingEvidenceItem, ...]
    notes: tuple[str, ...]


def _missing_explanation(requirement_id: str, status: str) -> str:
    requirement = REQUIREMENTS_BY_ID[requirement_id]
    if status == STATUS_NOT_ESTABLISHED:
        return (
            f"{requirement.title} is required by this example policy, but no qualifying "
            "source-backed evidence was located in the uploaded documents. "
            "This does not mean the patient clinically fails the criterion."
        )
    return (
        f"{requirement.title} could not be fully verified from available records and "
        "needs clinician review before it can be treated as established."
    )


def _document_coverage(
    db: Session,
    patient_id: str,
    evaluation: PolicyEvaluation,
) -> dict[str, set[str]]:
    """Map document_id -> requirement ids it helps establish via accepted candidates."""
    supported_ids = {
        item.requirement_id
        for item in evaluation.requirements
        if item.status == STATUS_SUPPORTED
    }
    if not supported_ids:
        return {}

    accepted_ids = {
        candidate_id
        for item in evaluation.requirements
        if item.status == STATUS_SUPPORTED
        for candidate_id in item.accepted_candidate_ids
    }
    candidates = (
        db.query(EvidenceCandidate)
        .options(joinedload(EvidenceCandidate.document))
        .filter(
            EvidenceCandidate.patient_id == patient_id,
            EvidenceCandidate.policy_id == evaluation.policy_id,
            EvidenceCandidate.id.in_(accepted_ids) if accepted_ids else False,
        )
        .all()
    )

    coverage: dict[str, set[str]] = {}
    for candidate in candidates:
        if candidate.verification_status != CANDIDATE_ACCEPTED:
            continue
        if candidate.requirement_id not in supported_ids:
            continue
        coverage.setdefault(candidate.document_id, set()).add(candidate.requirement_id)
    return coverage


def _exact_min_packet(
    coverage: dict[str, set[str]],
    documents: dict[str, Document],
    required: set[str],
) -> list[str]:
    """Exact weighted set cover for small n: minimize (doc count, page count)."""
    doc_ids = [doc_id for doc_id, reqs in coverage.items() if reqs & required]
    if not doc_ids:
        return []

    best: list[str] | None = None
    best_key: tuple[int, int] | None = None

    for size in range(1, len(doc_ids) + 1):
        for combo in combinations(doc_ids, size):
            covered: set[str] = set()
            for doc_id in combo:
                covered |= coverage[doc_id]
            if not required.issubset(covered):
                continue
            pages = sum(documents[doc_id].page_count for doc_id in combo)
            key = (len(combo), pages)
            if best_key is None or key < best_key:
                best_key = key
                best = list(combo)
        if best is not None:
            # Smallest cardinality found; no need to try larger sets.
            break

    return best or []


def _greedy_packet(
    coverage: dict[str, set[str]],
    documents: dict[str, Document],
    required: set[str],
) -> list[str]:
    remaining = set(required)
    selected: list[str] = []
    available = set(coverage)

    while remaining and available:
        def score(doc_id: str) -> tuple[float, int, str]:
            newly = len(coverage[doc_id] & remaining)
            pages = max(documents[doc_id].page_count, 1)
            # Higher newly-covered per page is better; tie-break fewer pages.
            return (-newly / pages, pages, doc_id)

        pick = min(available, key=score)
        newly = coverage[pick] & remaining
        available.remove(pick)
        if not newly:
            continue
        selected.append(pick)
        remaining -= newly

    return selected


def build_evidence_packet(
    db: Session,
    patient_id: str,
    *,
    policy_id: str = FICTIONAL_POLICY_ID,
    evaluation: PolicyEvaluation | None = None,
) -> EvidencePacket:
    evaluation = evaluation or evaluate_patient_policy(
        db, patient_id, policy_id=policy_id, persist=True
    )

    supported = {
        item.requirement_id
        for item in evaluation.requirements
        if item.status == STATUS_SUPPORTED
    }
    coverage = _document_coverage(db, patient_id, evaluation)
    documents = {
        doc.id: doc
        for doc in db.query(Document).filter(Document.patient_id == patient_id).all()
    }

    if len(coverage) <= 12:
        selected_ids = _exact_min_packet(coverage, documents, supported)
    else:
        selected_ids = _greedy_packet(coverage, documents, supported)

    covered_by_packet: set[str] = set()
    selected_docs: list[PacketDocument] = []
    for doc_id in selected_ids:
        req_ids = tuple(sorted(coverage.get(doc_id, set()) & supported))
        covered_by_packet.update(req_ids)
        doc = documents[doc_id]
        selected_docs.append(
            PacketDocument(
                document_id=doc.id,
                source_label=doc.source_label or doc.original_filename,
                original_filename=doc.original_filename,
                document_type=doc.document_type,
                page_count=doc.page_count,
                covers_requirement_ids=req_ids,
                covers_requirement_titles=tuple(
                    REQUIREMENTS_BY_ID[req_id].title for req_id in req_ids
                ),
            )
        )

    omitted = tuple(
        sorted(
            doc_id
            for doc_id in coverage
            if doc_id not in selected_ids
        )
    )

    missing: list[MissingEvidenceItem] = []
    for item in evaluation.requirements:
        if item.status not in {STATUS_NOT_ESTABLISHED, STATUS_NEEDS_REVIEW}:
            continue
        # Only list NEEDS_REVIEW in missing-info when nothing was accepted for it.
        if item.status == STATUS_NEEDS_REVIEW and item.accepted_candidate_ids:
            continue
        missing.append(
            MissingEvidenceItem(
                requirement_id=item.requirement_id,
                title=item.title,
                status=item.status,
                explanation=_missing_explanation(item.requirement_id, item.status),
                suggested_document_types=tuple(item.suggested_document_types),
            )
        )

    notes: list[str] = [
        "Packet selection uses only accepted, source-verified evidence.",
        "Optimization never overrides verification correctness.",
        evaluation.disclaimer,
    ]
    if omitted:
        notes.append(
            f"Omitted {len(omitted)} redundant document(s) that did not add uncovered requirements."
        )

    return EvidencePacket(
        patient_id=patient_id,
        policy_id=evaluation.policy_id,
        policy_name=evaluation.policy_name,
        disclaimer=evaluation.disclaimer,
        covered_requirement_ids=tuple(sorted(covered_by_packet)),
        uncovered_requirement_ids=tuple(sorted(supported - covered_by_packet)),
        selected_documents=tuple(selected_docs),
        omitted_document_ids=omitted,
        total_pages=sum(doc.page_count for doc in selected_docs),
        missing_evidence=tuple(missing),
        notes=tuple(notes),
    )

